/* ── índice y anotador ── */
const CATS = [...new Set(GLOSSARY.map(e => e.c))];
const BY_ID = Object.create(null);
const KEYS = new Map();   // alias en minúsculas → [{ e, a, cs }]
for (const e of GLOSSARY) {
  if (e.t[0] === "=") { e.t = e.t.slice(1); e.a.unshift("=" + e.t); } else e.a.unshift(e.t);
  BY_ID[e.id] = e;
  for (let a of e.a) {
    let cs = false;
    if (a[0] === "=") { cs = true; a = a.slice(1); }
    if (!/[a-záéíóúñü]/.test(a)) cs = true;
    const k = a.toLowerCase(), list = KEYS.get(k) || [];
    if (!list.some(x => x.e === e && x.a === a)) list.push({ e, a, cs });
    KEYS.set(k, list);
  }
}
const ALIASES = [...new Set([...KEYS.values()].flat().map(x => x.a))].sort((a, b) => b.length - a.length);
const escRx = s => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const RX = new RegExp("(?<![\\p{L}\\p{N}_@]|[\\p{L}\\p{N}][-/])(?:" + ALIASES.map(escRx).join("|") + ")(?:e?s)?(?![\\p{L}\\p{N}_]|[-/@][\\p{L}\\p{N}])", "giu");

function resolve(m) {
  const cands = [m]; if (/es$/i.test(m)) cands.push(m.slice(0, -2)); if (/s$/i.test(m)) cands.push(m.slice(0, -1));
  for (const c of cands) {
    const list = KEYS.get(c.toLowerCase()); if (!list) continue;
    const hit = list.find(x => x.cs ? x.a === c : true);
    if (hit) return hit.e;
  }
  return null;
}
const esc = s => String(s ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
// recorre el texto y llama a fn(entrada, coincidencia, índice) por cada término reconocido
function scan(text, fn) {
  RX.lastIndex = 0; let m;
  while ((m = RX.exec(text))) { const e = resolve(m[0]); if (e) fn(e, m[0], m.index); }
}
/* Devuelve HTML escapado con los términos envueltos en <span class="gl">. Con «seen» (un Set compartido)
   solo se marca la primera aparición de cada término en ese bloque. */
function annotate(text, seen) {
  text = String(text ?? ""); let out = "", last = 0;
  scan(text, (e, m, i) => {
    if (i < last || (seen && seen.has(e.id))) return;
    if (seen) seen.add(e.id);
    out += esc(text.slice(last, i)) + `<span class="gl" data-g="${e.id}">${esc(m)}</span>`;
    last = i + m.length;
  });
  return out + esc(text.slice(last));
}
// términos que aparecen en uno o más textos, en orden de aparición y sin repetir
function termsIn(...texts) {
  const ids = []; for (const t of texts) scan(String(t ?? ""), e => { if (!ids.includes(e.id)) ids.push(e.id); });
  return ids.map(id => BY_ID[id]);
}
const NOT_MAIN = new Set(["Conceptos"]);
// término principal de una opción: el primer servicio o componente que se menciona
function mainTerm(text) {
  const ts = termsIn(text);
  return ts.find(e => !NOT_MAIN.has(e.c)) || ts[0] || null;
}

const API = { GLOSSARY, CATS, BY_ID, annotate, termsIn, mainTerm, resolve };
if (typeof module !== "undefined" && module.exports) module.exports = API;
root.SAAGloss = API;
